 function reset(){setup();S.units=[];S.selected=null;}function make(name,side=1,q=0,r=0){const def=HeroRegistry.list().find(d=>ContentViews.hero(d.id).name===name),h=createRuntimeEntityInstance({definitionId:def.id,side,hero:true,q,r});S.units.push(h);return h}function card(id,h){const c=createEquipmentCardInstance(id,h.side);S.hands[h.side].push(c);return c}
 test("Equipment: confirmed deck has 7 designs / 14 copies",()=>{return JSON.stringify([EquipmentRegistry.list().filter(c=>c.class==='INF').length,DeckRuntimeBuilder.buildEquipmentIds('DECK_DUEL_STANDARD_001').filter(id=>EquipmentRegistry.get(id).class==='INF').length])===JSON.stringify([7,14])});
 test("Equipment: Hammer normal Attack gains 1 without persistent buff",()=>{reset();let h=make('Est'),e=make('Rodoc',2,1,0);S.selected=h;S.attackChoice={card:card('EQUIP_INF_ATK_001',h)};startAttack(h,e);resolveCombat();return JSON.stringify([e.hp,h.damageBuff,h.attacked,S.hands[1].length])===JSON.stringify([1,0,true,0])});
