 test("Equipment: Shoes buffs distant troops and Heroes without commit or queued damage gear",()=>{reset();let h7=make('Est'),t7=troop('INF',1,5,0);h7.moved=true;h7.movementCostSpent=1;const shoes=card('EQUIP_INF_ATK_003',h7);EquipmentCore.begin(h7,shoes);HeroCore.select(h7);HeroCore.select(t7);HeroCore.commit();return JSON.stringify([h7.moveBuff,t7.moveBuff,h7.attacked,!!h7.queuedAttackEquipment,canMoveFurther(h7),duelUsage().attackCard[1]])===JSON.stringify([1,1,false,false,true,1])});
